#!/usr/bin/env bash
# build-web.sh — assemble a trimmed, deployable static bundle in dist/.
# The app is 100% client-side; dist/ can be uploaded to any static host
# (GitHub Pages, Cloudflare Pages/R2, Netlify, S3+CloudFront).
#
# Excludes everything not needed at runtime: the data pipeline & downloads,
# raw atlas source PNGs (the baked veg-atlas.png replaces them), review shots,
# per-feature capture view lists, and serve.py/snap.py (dev tooling).
set -euo pipefail
cd "$(dirname "$0")"
npm run build
OUT="dist"

# Host helpers not generated by Vite.
cat > "$OUT/_headers" <<'HDR'
# Cloudflare Pages / Netlify cache + security policy.
# Bulk height/imagery tiles live on R2 (cached there); only code + small baked assets are here.

# Security hygiene for the whole static site (no backend, so this is defence-in-depth):
# nosniff stops MIME confusion, referrer-policy limits leakage, permissions-policy denies APIs
# the app never uses. No X-Frame-Options on purpose — embedding the demo in a blog/iframe is fine
# and there is nothing sensitive to clickjack.
/*
  X-Content-Type-Options: nosniff
  Referrer-Policy: strict-origin-when-cross-origin
  Permissions-Policy: geolocation=(), microphone=(), camera=(), payment=(), usb=()

/terrain/public/*.png
  Cache-Control: public, max-age=31536000, immutable
/*.html
  Cache-Control: no-cache
/terrain/src/*
  Cache-Control: no-cache
HDR

echo "built $OUT/"
du -sh "$OUT" | sed 's/^/  size: /'
echo "  files: $(find "$OUT" -type f | wc -l | tr -d ' ')"
echo
echo "deploy (pick one):"
echo "  • GitHub Pages : push dist/ to a gh-pages branch (or set Pages source to /dist)"
echo "  • Cloudflare   : npx wrangler pages deploy dist --project-name grand-teton"
echo "  • Netlify      : npx netlify deploy --dir dist --prod"
echo "  • local check  : (cd dist && python3 -m http.server 8130) → http://localhost:8130/"
